deepml motion 0.3
module corpus.deepml_motion.example_04251
policy deterministic
policy no_network
skeleton Rig04251 { joint Root parent none joint Hip parent Root joint FootL parent Hip joint FootR parent Hip }
procedural animation Procedural04251 seed 4251 {
  trajectory = predict_trajectory(velocity, horizon=1.0s)
  match = motion_match(database="local:motions_3", trajectory=trajectory)
  constrain contact FootL to ground when phase < 0.5
  constrain contact FootR to ground when phase >= 0.5
}
layered state_machine Layers04251 { base: Locomotion upper: Gesture additive: Breathing }
synchronize Procedural04251 with scene.Actor1 and timeline.Sequence0

